16	McpSetupResult run_mcp_setup_command(wxWindow* parent, const std::vector<std::string>& arguments)
17	{
18	    if (arguments.empty()) throw std::invalid_argument("Missing setup executable");
19	    wxDialog progress(parent, wxID_ANY, "Connecting AI tool", wxDefaultPosition, parent->FromDIP(wxSize(460, 140)));
20	    auto* label = new wxStaticText(&progress, wxID_ANY, "Saving the MCP entry using the client's own CLI...");
21	    auto* layout = new wxBoxSizer(wxVERTICAL);
22	    layout->Add(label, 1, wxEXPAND | wxALL, progress.FromDIP(16));
23	    progress.SetSizer(layout);
24	    wxProcess process(&progress);
25	    process.Redirect();
26	    std::vector<wxString> values;
27	    for (const auto& value : arguments) values.push_back(wxString::FromUTF8(value));
28	    std::vector<const wchar_t*> argv;
29	    for (const auto& value : values) argv.push_back(value.wc_str());
30	    argv.push_back(nullptr);
31	    const auto pid = wxExecute(argv.data(), wxEXEC_ASYNC | wxEXEC_HIDE_CONSOLE, &process);
32	    if (pid <= 0) return {false, "Could not start the client CLI. Use Copy or check its installation."};
33	    process.CloseOutput();
34	    std::string output;
35	    bool timed_out = false;
36	    int exit_code = -1;
37	    const auto started = std::chrono::steady_clock::now();
38	    auto drain = [&] {
39	        for (auto* stream : {process.GetInputStream(), process.GetErrorStream()}) {
40	            while (stream && stream->CanRead()) {
41	                char buffer[4096];
42	                stream->Read(buffer, sizeof buffer);
43	                const auto size = stream->LastRead();
44	                if (!size) break;
45	                if (output.size() < 65536) output.append(buffer, std::min(size, 65536 - output.size()));
46	            }
47	        }
48	    };
49	    wxTimer timer(&progress);
50	    progress.Bind(wxEVT_TIMER, [&](wxTimerEvent&) {
51	        drain();
52	        const auto elapsed = std::chrono::steady_clock::now() - started;
53	        if (!timed_out && elapsed > std::chrono::seconds(30)) {
54	            timed_out = true;
55	            label->SetLabel("The setup command timed out. Stopping it...");
56	            wxProcess::Kill(pid, wxSIGTERM);
57	        } else if (timed_out && elapsed > std::chrono::seconds(32)) wxProcess::Kill(pid, wxSIGKILL);
58	    });
59	    progress.Bind(wxEVT_CLOSE_WINDOW, [&](wxCloseEvent& event) {
60	        if (event.CanVeto()) event.Veto(); // Keep the owned process alive only while its monitor exists.
61	    });
62	    // wxDialog handles Cancel separately from window-close events. Do not
63	    // destroy the process monitor while the CLI may still be saving settings.
64	    progress.Bind(wxEVT_BUTTON, [](wxCommandEvent&) {}, wxID_CANCEL);
65	    progress.Bind(wxEVT_END_PROCESS, [&](wxProcessEvent& event) {
66	        drain(); exit_code = event.GetExitCode(); timer.Stop(); progress.EndModal(wxID_OK);
67	    });
68	    timer.Start(30);
69	    progress.ShowModal();
70	    if (timed_out) return {false, "Setup timed out; the client config may have changed. Inspect it before trying again.\n" + output};
71	    return {exit_code == 0, "Client CLI exited with code " + std::to_string(exit_code) + ".\n" + output};
72	}
