30	CatalogPaths default_catalog_paths()
31	{
32	    CatalogPaths paths;
33	#ifdef _WIN32
34	    paths.windows = true;
35	    const auto profile = env("USERPROFILE");
36	    paths.home = profile.empty() ? fs::current_path() : fs::u8path(profile);
37	    const auto appdata = env("APPDATA");
38	    paths.config_home = appdata.empty() ? paths.home : fs::u8path(appdata);
39	#elif defined(__APPLE__)
40	    const auto home = env("HOME");
41	    paths.home = home.empty() ? fs::current_path() : fs::u8path(home);
42	    paths.config_home = paths.home / "Library" / "Application Support";
43	#else
44	    const auto home = env("HOME");
45	    paths.home = home.empty() ? fs::current_path() : fs::u8path(home);
46	    const auto xdg = env("XDG_CONFIG_HOME");
47	    paths.config_home = xdg.empty() ? paths.home / ".config" : fs::u8path(xdg);
48	#endif
49	    return paths;
