80	std::vector<CatalogItem> make_catalog(const std::string& helper, const std::string& discovery, const CatalogPaths& paths,
81	                                      std::vector<std::string> launch_arguments)
82	{
83	    const auto entries = connection_entries(helper, discovery, paths.windows, std::move(launch_arguments));
84	    const std::vector<fs::path> configs{
85	        paths.home / ".claude.json",
86	        paths.home / ".codex" / "config.toml",
87	        paths.config_home / "Claude" / "claude_desktop_config.json",
88	        paths.config_home / "Claude" / "claude_desktop_config.json",
89	        paths.home / ".cursor" / "mcp.json",
90	        paths.config_home / "Code" / "User" / "mcp.json",
91	    };
92	    std::vector<CatalogItem> items;
93	    items.reserve(entries.size());
94	    for (std::size_t i = 0; i < entries.size(); ++i) {
95	        CatalogItem item;
96	        item.entry = entries[i];
97	        item.config_path = configs[i];
98	        if (!item.entry.cli) item.json_root = item.entry.id == "code" ? "servers" : "mcpServers";
99	        std::error_code error;
100	        item.detected = fs::exists(item.config_path, error) || !command_on_path(item.entry.id).empty();
101	        items.push_back(std::move(item));
102	    }
103	    return items;
104	}
