29	    using nlohmann::json;
30	    launch_arguments.insert(launch_arguments.end(), {"--discovery", discovery});
31	    const json server{{"command", bridge}, {"args", launch_arguments}};
32	    std::string invocation = quote_argument(bridge, windows);
